// Copies the labeller rules (prompt v3) verbatim into mod/hooks/lib/rules.ts.
// `node scripts/rules.mjs` writes it; `--check` fails when the copy differs.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const src = join(root, '.scratch/claude-marks/prototype-labeller/labeller-prompt.v3.md')
const dst = join(root, 'mod/hooks/lib/rules.ts')
const rules = readFileSync(src, 'utf8').replace(/\r\n/g, '\n')
const out =
  '// Generated by scripts/rules.mjs from .scratch/claude-marks/prototype-labeller/labeller-prompt.v3.md.\n' +
  '// The labeller rules, verbatim. Do not edit; rerun `node scripts/rules.mjs`.\n' +
  `export const RULES = ${JSON.stringify(rules)}\n`

if (process.argv.includes('--check')) {
  const have = readFileSync(dst, 'utf8').replace(/\r\n/g, '\n')
  if (have !== out) {
    console.error('mod/hooks/lib/rules.ts differs from labeller-prompt.v3.md; run node scripts/rules.mjs')
    process.exit(1)
  }
  console.log('rules.ts matches labeller-prompt.v3.md')
} else {
  writeFileSync(dst, out)
  console.log('wrote mod/hooks/lib/rules.ts')
}
